void ubc_check(const uint32_t W[80], uint32_t dvmask[1])
{
	size_t        i;
	unsigned char common, left, right;
	uint32_t      b1, b2, lhs, eqn;
	*dvmask = -1;
#pragma GCC unroll 65534
	for(i = 0; i < sizeof ubcs / sizeof *ubcs; i++) {
		common = ubcs[i].i <= ubcs[i].j ? ubcs[i].i : ubcs[i].j;
		left   = ubcs[i].i - common;
		right  = ubcs[i].j - common;

		if(i > 64 && !(*dvmask & ubcs[i].dvs)) continue;
		b1  = W[ubcs[i].a] >> left;
		b2  = W[ubcs[i].b] >> right;
		lhs =    (b1 ^ b2) >> common & 1;
		eqn = ubcs[i].c ? 0 - lhs : lhs - 1;
		*dvmask &= eqn | ~ubcs[i].dvs;
		if(i == 64 && !*dvmask) break;
	}
}

